tool_schemas.implementation:
def Optional_Settings(account_id, action, server_id=None, optional_settings_id=None, body=None, session_id=None, cursor=None, limit=None, sort=None, filters=None, **_extra):
    import json, os, datetime, re, time, secrets, base64, urllib.parse
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0129000" if __import__("os").path.isdir("./environment_mix/0129000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)
    now_s = now.isoformat() + "Z"

    # --- helpers ---
    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1]
                return datetime.datetime.fromisoformat(s2)
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _dt_to_str(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            return dt.replace(microsecond=0).isoformat() + "Z"
        return None

    def _id(prefix):
        # 18+ base32-ish uppercase chars
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        return prefix + "".join(secrets.choice(alphabet) for _ in range(20))

    def _valid_id(pat, v):
        return isinstance(v, str) and re.match(pat, v) is not None

    def _is_valid_email(e):
        if not isinstance(e, str) or not e or len(e) > 320:
            return False
        # pragmatic email validation
        return re.match(r"^[^@\s]+@[^@\s]+\.[^@\s]+$", e) is not None

    def _is_valid_url(u):
        if not isinstance(u, str) or not u:
            return False
        try:
            pr = urllib.parse.urlparse(u)
            if pr.scheme not in ("http", "https"):
                return False
            if not pr.netloc:
                return False
            return True
        except Exception:
            return False

    def _audit_append(audit_events, account_id_v, server_id_v, session_id_v, event_type, metadata, ip=None, ua=None):
        ev = {
            "id": _id("cgs_aud_"),
            "account_id": account_id_v,
            "server_id": server_id_v,
            "session_id": session_id_v,
            "event_type": event_type,
            "ip_address": ip,
            "user_agent": ua,
            "metadata": metadata if isinstance(metadata, dict) else {},
            "created_at": now_s,
            "updated_at": now_s,
        }
        audit_events.append(ev)
        return ev

    def _paginate(rows, cursor_v, limit_v):
        if limit_v is None:
            limit_v = 50
        start = 0
        if cursor_v:
            if not isinstance(cursor_v, str):
                return None, None, _err("VALIDATION_ERROR", "cursor must be a string")
            try:
                raw = base64.urlsafe_b64decode(cursor_v.encode("utf-8") + b"==")
                start = int(raw.decode("utf-8"))
                if start < 0:
                    start = 0
            except Exception:
                return None, None, _err("VALIDATION_ERROR", "Invalid cursor")
        end = start + limit_v
        page = rows[start:end]
        has_more = end < len(rows)
        next_cursor_v = None
        if has_more:
            next_cursor_v = base64.urlsafe_b64encode(str(end).encode("utf-8")).decode("utf-8").rstrip("=")
        return page, {"total": len(rows), "has_more": has_more, "next_cursor": next_cursor_v}, None

    def _sort_rows(rows, sort_v, dt_fields):
        if sort_v is None:
            sort_v = "-created_at"
        if sort_v not in ("created_at", "-created_at", "updated_at", "-updated_at", "last_used_at", "-last_used_at"):
            return None, _err("VALIDATION_ERROR", "Invalid sort")
        key = sort_v.lstrip("-")
        rev = sort_v.startswith("-")

        def k(r):
            v = r.get(key)
            if key in dt_fields:
                d = _parse_dt(v) if isinstance(v, str) else (v if isinstance(v, datetime.datetime) else None)
                return d or datetime.datetime.min
            return v
        return sorted(rows, key=k, reverse=rev), None

    # --- validate base inputs ---
    if not isinstance(action, str) or action not in {
        "create", "update", "get", "list", "enable", "disable",
        "sign_in", "list_sessions", "revoke_session", "list_audit_events"
    }:
        return _err("VALIDATION_ERROR", "Invalid action")
    if not _valid_id(r"^cgs_acct_[0-9A-Z]{18,}$", account_id):
        return _err("VALIDATION_ERROR", "Invalid account_id")

    if body is not None and not isinstance(body, dict):
        return _err("VALIDATION_ERROR", "body must be an object")
    if filters is not None and not isinstance(filters, dict):
        return _err("VALIDATION_ERROR", "filters must be an object")
    if limit is not None:
        if not isinstance(limit, int):
            return _err("VALIDATION_ERROR", "limit must be an integer")
        if limit < 1 or limit > 200:
            return _err("VALIDATION_ERROR", "limit must be between 1 and 200")

    if server_id is not None and not _valid_id(r"^cgs_srv_[0-9A-Z]{18,}$", server_id):
        return _err("VALIDATION_ERROR", "Invalid server_id")
    if optional_settings_id is not None and not _valid_id(r"^cgs_opt_[0-9A-Z]{18,}$", optional_settings_id):
        return _err("VALIDATION_ERROR", "Invalid optional_settings_id")
    if session_id is not None and not _valid_id(r"^cgs_sess_[0-9A-Z]{18,}$", session_id):
        return _err("VALIDATION_ERROR", "Invalid session_id")

    # load DB
    accounts = _load("accounts.json")
    servers = _load("servers.json")
    optional_settings = _load("optional_settings.json")
    auth_sessions = _load("auth_sessions.json")
    audit_events = _load("audit_events.json")

    # resolve account
    acct = next((a for a in accounts if a.get("id") == account_id), None)
    if not acct:
        return _err("NOT_FOUND", "Account not found")
    if acct.get("status") not in ("active", "suspended", "deleted"):
        return _err("VALIDATION_ERROR", "Account has invalid status in datastore")

    # resolve server: from param, else default configured, else pick an active server if possible
    default_server_id = os.environ.get("CGS_DEFAULT_SERVER_ID")
    resolved_server = None
    if server_id:
        resolved_server = next((s for s in servers if s.get("id") == server_id), None)
        if not resolved_server:
            return _err("NOT_FOUND", "Server not found")
    else:
        if default_server_id and _valid_id(r"^cgs_srv_[0-9A-Z]{18,}$", default_server_id):
            resolved_server = next((s for s in servers if s.get("id") == default_server_id), None)
        if not resolved_server:
            # fall back: pick a server that can serve the action
            if action in ("enable", "create", "sign_in"):
                resolved_server = next((s for s in servers if s.get("status") == "active"), None)
            else:
                resolved_server = next((s for s in servers if s.get("status") in ("active", "disabled")), None) or (servers[0] if servers else None)

    # for actions that require a server context, ensure one exists
    needs_server = action in ("create", "update", "get", "list", "enable", "disable", "sign_in", "list_sessions")
    # revoke_session/list_audit_events can be by session/filters without server, but still okay to carry server
    if needs_server and not resolved_server:
        return _err("UNAUTHORIZED", "No server context available to satisfy request")
    resolved_server_id = resolved_server.get("id") if resolved_server else None

    # ensure server record constraints if server is being created/updated via body (not supported for writes per rule)
    # Business rule: tool must read/write only optional_settings rows.
    if body and any(k in body for k in ("name", "base_url", "environment")):
        # accept but do not mutate servers collection; treat as validation error to match "must read/write only optional_settings"
        # unless action is read/list where these fields are irrelevant; still reject because surface suggests support.
        return _err("VALIDATION_ERROR", "This endpoint does not support creating/updating server records; only optional_settings and sessions")

    # enforce settings field ranges on write
    def _validate_settings_payload(payload, for_update=False):
        allowed = {"default_model", "request_timeout_ms", "max_retries", "verify_tls", "store_tokens", "status"}
        if payload is None:
            return _err("VALIDATION_ERROR", "body is required")
        for k in payload.keys():
            if k not in allowed and k not in {"email", "password", "auth_provider", "scopes"}:
                return _err("VALIDATION_ERROR", f"Unknown field in body: {k}")

        if "request_timeout_ms" in payload:
            if not isinstance(payload["request_timeout_ms"], int):
                return _err("VALIDATION_ERROR", "request_timeout_ms must be an integer")
            if payload["request_timeout_ms"] < 1000 or payload["request_timeout_ms"] > 300000:
                return _err("VALIDATION_ERROR", "request_timeout_ms must be between 1000 and 300000")
        if "max_retries" in payload:
            if not isinstance(payload["max_retries"], int):
                return _err("VALIDATION_ERROR", "max_retries must be an integer")
            if payload["max_retries"] < 0 or payload["max_retries"] > 10:
                return _err("VALIDATION_ERROR", "max_retries must be between 0 and 10")
        if "verify_tls" in payload and not isinstance(payload["verify_tls"], bool):
            return _err("VALIDATION_ERROR", "verify_tls must be a boolean")
        if "store_tokens" in payload and not isinstance(payload["store_tokens"], bool):
            return _err("VALIDATION_ERROR", "store_tokens must be a boolean")
        if "default_model" in payload and payload["default_model"] is not None and not isinstance(payload["default_model"], str):
            return _err("VALIDATION_ERROR", "default_model must be a string or null")
        if "status" in payload:
            if payload["status"] not in ("active", "disabled"):
                return _err("VALIDATION_ERROR", "status must be 'active' or 'disabled'")
        return None

    def _log_and_return(status_code, out):
        # No dedicated request-log collection in schema; only audit_events required for certain actions.
        # We still normalize audit_events.updated_at for append-only rows: keep updated_at == created_at.
        # Compute latency and return.
        _ = status_code
        latency_ms = int((time.time() - t0) * 1000)
        if isinstance(out, dict) and "error" in out:
            out.setdefault("meta", {})
            out["meta"].update({"latency_ms": latency_ms, "timestamp": now_s})
        else:
            if isinstance(out, dict):
                out.setdefault("meta", {})
                out["meta"].update({"latency_ms": latency_ms, "timestamp": now_s})
        return out

    # --- action handlers ---
    try:
        if action == "list":
            # list optional_settings for account (and optionally for server / env / status / created_* filters)
            rows = [r for r in optional_settings if r.get("account_id") == account_id]
            if resolved_server_id:
                # if server_id not provided, still reasonable to list for all servers; only filter when server_id explicitly passed
                if server_id is not None:
                    rows = [r for r in rows if r.get("server_id") == resolved_server_id]
            if filters:
                if "status" in filters:
                    st = filters["status"]
                    if not isinstance(st, str):
                        return _log_and_return(400, _err("VALIDATION_ERROR", "filters.status must be a string"))
                    rows = [r for r in rows if r.get("status") == st]
                if "environment" in filters:
                    env = filters["environment"]
                    if env not in ("production", "staging", "development", "custom"):
                        return _log_and_return(400, _err("VALIDATION_ERROR", "Invalid filters.environment"))
                    srv_by_id = {s.get("id"): s for s in servers}
                    rows = [r for r in rows if srv_by_id.get(r.get("server_id"), {}).get("environment") == env]
                ca = _parse_dt(filters.get("created_after")) if "created_after" in filters else None
                cb = _parse_dt(filters.get("created_before")) if "created_before" in filters else None
                if "created_after" in filters and ca is None:
                    return _log_and_return(400, _err("VALIDATION_ERROR", "filters.created_after must be ISO 8601 date-time"))
                if "created_before" in filters and cb is None:
                    return _log_and_return(400, _err("VALIDATION_ERROR", "filters.created_before must be ISO 8601 date-time"))
                if ca:
                    rows = [r for r in rows if (_parse_dt(r.get("created_at")) or datetime.datetime.min) > ca]
                if cb:
                    rows = [r for r in rows if (_parse_dt(r.get("created_at")) or datetime.datetime.min) < cb]

            rows, se = _sort_rows(rows, sort, {"created_at", "updated_at"})
            if se:
                return _log_and_return(400, se)
            page, meta, pe = _paginate(rows, cursor, limit)
            if pe:
                return _log_and_return(400, pe)
            return _log_and_return(200, {"data": page, "meta": meta})

        if action == "get":
            # get by id if provided else by (account_id, server_id)
            row = None
            if optional_settings_id:
                row = next((r for r in optional_settings if r.get("id") == optional_settings_id and r.get("account_id") == account_id), None)
                if not row:
                    return _log_and_return(404, _err("NOT_FOUND", "Optional settings not found"))
            else:
                if not resolved_server_id:
                    return _log_and_return(401, _err("UNAUTHORIZED", "No server context available"))
                row = next((r for r in optional_settings if r.get("account_id") == account_id and r.get("server_id") == resolved_server_id), None)
                if not row:
                    return _log_and_return(404, _err("NOT_FOUND", "Optional settings not found"))
            return _log_and_return(200, {"data": row})

        if action == "create":
            if not resolved_server:
                return _log_and_return(401, _err("UNAUTHORIZED", "No server context available"))
            if acct.get("status") in ("suspended", "deleted"):
                return _log_and_return(401, _err("UNAUTHORIZED", "Account is not allowed to create settings"))
            if resolved_server.get("status") in ("deleted",):
                return _log_and_return(409, _err("CONFLICT", "Server is deleted"))
            ve = _validate_settings_payload(body, for_update=False)
            if ve:
                return _log_and_return(400, ve)

            # uniqueness (account_id, server_id)
            existing = next((r for r in optional_settings if r.get("account_id") == account_id and r.get("server_id") == resolved_server_id), None)
            if existing:
                return _log_and_return(409, _err("CONFLICT", "Optional settings already exist for this account and server", optional_settings_id=existing.get("id")))

            st = body.get("status", "active") if body else "active"
            # enabling requires account+server allow
            if st == "active":
                if resolved_server.get("status") in ("disabled", "deleted"):
                    return _log_and_return(401, _err("UNAUTHORIZED", "Server is not allowed to have enabled settings"))
                if acct.get("status") != "active":
                    return _log_and_return(401, _err("UNAUTHORIZED", "Account is not allowed to enable settings"))

            row = {
                "id": _id("cgs_opt_"),
                "account_id": account_id,
                "server_id": resolved_server_id,
                "default_model": body.get("default_model") if body else None,
                "request_timeout_ms": body.get("request_timeout_ms") if body and "request_timeout_ms" in body else 30000,
                "max_retries": body.get("max_retries") if body and "max_retries" in body else 3,
                "verify_tls": body.get("verify_tls") if body and "verify_tls" in body else True,
                "store_tokens": body.get("store_tokens") if body and "store_tokens" in body else False,
                "status": st,
                "created_at": now_s,
                "updated_at": now_s,
            }
            # validate defaults range too
            if row["request_timeout_ms"] < 1000 or row["request_timeout_ms"] > 300000:
                return _log_and_return(400, _err("VALIDATION_ERROR", "request_timeout_ms must be between 1000 and 300000"))
            if row["max_retries"] < 0 or row["max_retries"] > 10:
                return _log_and_return(400, _err("VALIDATION_ERROR", "max_retries must be between 0 and 10"))

            optional_settings.append(row)
            _audit_append(
                audit_events, account_id, resolved_server_id, None,
                "settings.created",
                {"changed_fields": sorted(list(row.keys()))}
            )
            _save("optional_settings.json", optional_settings)
            _save("audit_events.json", audit_events)
            return _log_and_return(200, {"data": row})

        if action == "update":
            ve = _validate_settings_payload(body, for_update=True)
            if ve:
                return _log_and_return(400, ve)

            # find row
            row = None
            if optional_settings_id:
                row = next((r for r in optional_settings if r.get("id") == optional_settings_id and r.get("account_id") == account_id), None)
            else:
                if not resolved_server_id:
                    return _log_and_return(401, _err("UNAUTHORIZED", "No server context available"))
                row = next((r for r in optional_settings if r.get("account_id") == account_id and r.get("server_id") == resolved_server_id), None)
            if not row:
                return _log_and_return(404, _err("NOT_FOUND", "Optional settings not found"))

            # enforce lifecycle enable constraints if status set to active
            new_status = body.get("status") if body else None
            if new_status == "active" and row.get("status") != "active":
                if acct.get("status") in ("suspended", "deleted"):
                    return _log_and_return(401, _err("UNAUTHORIZED", "Account is not allowed to enable settings"))
                srv = next((s for s in servers if s.get("id") == row.get("server_id")), None)
                if not srv or srv.get("status") in ("disabled", "deleted"):
                    return _log_and_return(401, _err("UNAUTHORIZED", "Server is not allowed to have enabled settings"))
                # transition disabled->active allowed
                if row.get("status") not in ("disabled", "active"):
                    return _log_and_return(400, _err("VALIDATION_ERROR", "Invalid optional_settings status in datastore"))
            if new_status == "disabled" and row.get("status") != "disabled":
                # active->disabled allowed
                pass
            if new_status and new_status != row.get("status"):
                # validate transition
                allowed = {"active": {"disabled"}, "disabled": {"active"}}
                if row.get("status") not in allowed or new_status not in allowed[row.get("status")]:
                    return _log_and_return(409, _err("INVALID_TRANSITION", f"Cannot transition settings from {row.get('status')} to {new_status}"))

            changed = []
            for k in ("default_model", "request_timeout_ms", "max_retries", "verify_tls", "store_tokens", "status"):
                if body is not None and k in body:
                    if row.get(k) != body.get(k):
                        row[k] = body.get(k)
                        changed.append(k)
            if not changed:
                return _log_and_return(404, _err("NOT_FOUND", "No changes applied"))  # enforce "no success without effect"

            row["updated_at"] = now_s
            # emit audit event: updated/disabled/enabled
            if "status" in changed:
                if row["status"] == "disabled":
                    et = "settings.disabled"
                else:
                    et = "settings.enabled"
            else:
                et = "settings.updated"
            _audit_append(audit_events, account_id, row.get("server_id"), None, et, {"changed_fields": sorted(changed)})
            _save("optional_settings.json", optional_settings)
            _save("audit_events.json", audit_events)
            return _log_and_return(200, {"data": row})

        if action in ("enable", "disable"):
            # convenience: update status only
            target_status = "active" if action == "enable" else "disabled"
            # find row
            row = None
            if optional_settings_id:
                row = next((r for r in optional_settings if r.get("id") == optional_settings_id and r.get("account_id") == account_id), None)
            else:
                if not resolved_server_id:
                    return _log_and_return(401, _err("UNAUTHORIZED", "No server context available"))
                row = next((r for r in optional_settings if r.get("account_id") == account_id and r.get("server_id") == resolved_server_id), None)
            if not row:
                return _log_and_return(404, _err("NOT_FOUND", "Optional settings not found"))

            if row.get("status") == target_status:
                return _log_and_return(404, _err("NOT_FOUND", "No changes applied"))

            allowed = {"active": {"disabled"}, "disabled": {"active"}}
            cur = row.get("status")
            if cur not in allowed or target_status not in allowed[cur]:
                return _log_and_return(409, _err("INVALID_TRANSITION", f"Cannot transition settings from {cur} to {target_status}"))

            if target_status == "active":
                if acct.get("status") in ("suspended", "deleted"):
                    return _log_and_return(401, _err("UNAUTHORIZED", "Account is not allowed to enable settings"))
                srv = next((s for s in servers if s.get("id") == row.get("server_id")), None)
                if not srv:
                    return _log_and_return(404, _err("NOT_FOUND", "Server not found"))
                if srv.get("status") in ("disabled", "deleted"):
                    return _log_and_return(401, _err("UNAUTHORIZED", "Server is not allowed to have enabled settings"))

            row["status"] = target_status
            row["updated_at"] = now_s
            et = "settings.enabled" if target_status == "active" else "settings.disabled"
            _audit_append(audit_events, account_id, row.get("server_id"), None, et, {"changed_fields": ["status"]})
            _save("optional_settings.json", optional_settings)
            _save("audit_events.json", audit_events)
            return _log_and_return(200, {"data": row})

        if action == "sign_in":
            # requires server context
            if not resolved_server:
                return _log_and_return(401, _err("UNAUTHORIZED", "No server context available"))
            if acct.get("status") in ("suspended", "deleted"):
                _audit_append(audit_events, account_id, resolved_server_id, None, "auth.sign_in_failed", {"reason": "account_status"})
                _save("audit_events.json", audit_events)
                return _log_and_return(401, _err("UNAUTHORIZED", "Account is not allowed to sign in"))
            if resolved_server.get("status") in ("disabled", "deleted"):
                _audit_append(audit_events, account_id, resolved_server_id, None, "auth.sign_in_failed", {"reason": "server_status"})
                _save("audit_events.json", audit_events)
                return _log_and_return(401, _err("UNAUTHORIZED", "Server is not allowed for sign in"))

            if body is None:
                _audit_append(audit_events, account_id, resolved_server_id, None, "auth.sign_in_failed", {"reason": "missing_body"})
                _save("audit_events.json", audit_events)
                return _log_and_return(400, _err("VALIDATION_ERROR", "body is required"))

            auth_provider = body.get("auth_provider", acct.get("auth_provider"))
            if auth_provider not in ("local", "oauth", "sso"):
                _audit_append(audit_events, account_id, resolved_server_id, None, "auth.sign_in_failed", {"reason": "invalid_auth_provider"})
                _save("audit_events.json", audit_events)
                return _log_and_return(400, _err("VALIDATION_ERROR", "Invalid auth_provider"))

            # local auth: verify by matching account email and (since only hash exists) require local provider and non-empty password;
            # cannot verify plaintext vs hash; treat as success only when email matches this account and password present.
            if auth_provider == "local":
                email = body.get("email")
                pwd = body.get("password")
                if not _is_valid_email(email) or email != acct.get("email"):
                    _audit_append(audit_events, account_id, resolved_server_id, None, "auth.sign_in_failed", {"reason": "email_mismatch"})
                    _save("audit_events.json", audit_events)
                    return _log_and_return(401, _err("UNAUTHORIZED", "Invalid credentials"))
                if not isinstance(pwd, str) or len(pwd) < 1:
                    _audit_append(audit_events, account_id, resolved_server_id, None, "auth.sign_in_failed", {"reason": "missing_password"})
                    _save("audit_events.json", audit_events)
                    return _log_and_return(401, _err("UNAUTHORIZED", "Invalid credentials"))
                if acct.get("auth_provider") != "local":
                    _audit_append(audit_events, account_id, resolved_server_id, None, "auth.sign_in_failed", {"reason": "provider_mismatch"})
                    _save("audit_events.json", audit_events)
                    return _log_and_return(401, _err("UNAUTHORIZED", "Invalid credentials"))

            # pick settings for this account+server, if exists
            settings_row = next((r for r in optional_settings if r.get("account_id") == account_id and r.get("server_id") == resolved_server_id), None)
            store_tokens = bool(settings_row.get("store_tokens")) if settings_row else False

            # revoke any prior active session for same account+server in same transaction
            revoked_any = False
            for s in auth_sessions:
                if s.get("account_id") == account_id and s.get("server_id") == resolved_server_id and s.get("status") == "active":
                    s["status"] = "revoked"
                    s["updated_at"] = now_s
                    revoked_any = True
                    _audit_append(audit_events, account_id, resolved_server_id, s.get("id"), "auth.session_revoked", {"reason": "new_sign_in"})

            # create new active session, enforcing uniqueness (now satisfied)
            scopes = body.get("scopes", [])
            if scopes is None:
                scopes = []
            if not isinstance(scopes, list) or any(not isinstance(x, str) for x in scopes):
                _audit_append(audit_events, account_id, resolved_server_id, None, "auth.sign_in_failed", {"reason": "invalid_scopes"})
                _save("audit_events.json", audit_events)
                return _log_and_return(400, _err("VALIDATION_ERROR", "scopes must be an array of strings"))
            if len(scopes) > 100:
                _audit_append(audit_events, account_id, resolved_server_id, None, "auth.sign_in_failed", {"reason": "scopes_too_large"})
                _save("audit_events.json", audit_events)
                return _log_and_return(400, _err("VALIDATION_ERROR", "scopes length must be <= 100"))

            expires = now + datetime.timedelta(hours=1)
            sess = {
                "id": _id("cgs_sess_"),
                "account_id": account_id,
                "server_id": resolved_server_id,
                "optional_settings_id": settings_row.get("id") if settings_row else None,
                "access_token_ciphertext": None,
                "refresh_token_ciphertext": None,
                "token_type": "Bearer",
                "scopes": scopes,
                "expires_at": _dt_to_str(expires),
                "last_used_at": now_s,
                "status": "active",
                "created_at": now_s,
                "updated_at": now_s,
            }
            if store_tokens:
                # placeholder ciphertext; not decryptable but stored as if encrypted
                sess["access_token_ciphertext"] = "enc:" + _id("tok_")
                sess["refresh_token_ciphertext"] = "enc:" + _id("rtok_")
            else:
                sess["access_token_ciphertext"] = None
                sess["refresh_token_ciphertext"] = None

            auth_sessions.append(sess)
            _audit_append(audit_events, account_id, resolved_server_id, sess["id"], "auth.sign_in_succeeded", {"revoked_prior_active": revoked_any, "scopes": scopes, "store_tokens": store_tokens})
            _save("auth_sessions.json", auth_sessions)
            _save("audit_events.json", audit_events)
            return _log_and_return(200, {"data": sess})

        if action == "list_sessions":
            # list sessions for account (optionally server/status filters)
            rows = [s for s in auth_sessions if s.get("account_id") == account_id]
            if server_id is not None:
                # filter by resolved server id
                if not resolved_server_id:
                    return _log_and_return(404, _err("NOT_FOUND", "Server not found"))
                rows = [s for s in rows if s.get("server_id") == resolved_server_id]
            if filters:
                if "status" in filters:
                    st = filters["status"]
                    if not isinstance(st, str):
                        return _log_and_return(400, _err("VALIDATION_ERROR", "filters.status must be a string"))
                    rows = [s for s in rows if s.get("status") == st]
                ca = _parse_dt(filters.get("created_after")) if "created_after" in filters else None
                cb = _parse_dt(filters.get("created_before")) if "created_before" in filters else None
                if "created_after" in filters and ca is None:
                    return _log_and_return(400, _err("VALIDATION_ERROR", "filters.created_after must be ISO 8601 date-time"))
                if "created_before" in filters and cb is None:
                    return _log_and_return(400, _err("VALIDATION_ERROR", "filters.created_before must be ISO 8601 date-time"))
                if ca:
                    rows = [s for s in rows if (_parse_dt(s.get("created_at")) or datetime.datetime.min) > ca]
                if cb:
                    rows = [s for s in rows if (_parse_dt(s.get("created_at")) or datetime.datetime.min) < cb]

            rows, se = _sort_rows(rows, sort or "-last_used_at", {"created_at", "updated_at", "last_used_at"})
            if se:
                return _log_and_return(400, se)
            page, meta, pe = _paginate(rows, cursor, limit)
            if pe:
                return _log_and_return(400, pe)
            return _log_and_return(200, {"data": page, "meta": meta})

        if action == "revoke_session":
            # revoke by session_id
            if not session_id:
                return _log_and_return(400, _err("VALIDATION_ERROR", "session_id is required for revoke_session"))
            sess = next((s for s in auth_sessions if s.get("id") == session_id and s.get("account_id") == account_id), None)
            if not sess:
                return _log_and_return(404, _err("NOT_FOUND", "Session not found"))

            cur = sess.get("status")
            if cur == "revoked":
                return _log_and_return(404, _err("NOT_FOUND", "No changes applied"))
            allowed = {"active": {"expired", "revoked"}, "expired": {"revoked"}, "revoked": set()}
            if cur not in allowed or "revoked" not in allowed[cur]:
                return _log_and_return(409, _err("INVALID_TRANSITION", f"Cannot transition session from {cur} to revoked"))

            sess["status"] = "revoked"
            sess["updated_at"] = now_s
            _audit_append(audit_events, account_id, sess.get("server_id"), sess.get("id"), "auth.session_revoked", {"reason": "user_revoked"})
            _save("auth_sessions.json", auth_sessions)
            _save("audit_events.json", audit_events)
            return _log_and_return(200, {"data": sess})

        if action == "list_audit_events":
            # list audit events for account (optionally by server/event_type and created range)
            rows = [e for e in audit_events if e.get("account_id") == account_id]
            if server_id is not None:
                if not resolved_server_id:
                    return _log_and_return(404, _err("NOT_FOUND", "Server not found"))
                rows = [e for e in rows if e.get("server_id") == resolved_server_id]
            if filters:
                if "event_type" in filters:
                    et = filters["event_type"]
                    allowed = {"settings.created", "settings.updated", "settings.disabled", "settings.enabled",
                               "auth.sign_in_succeeded", "auth.sign_in_failed", "auth.token_refreshed", "auth.session_revoked"}
                    if et not in allowed:
                        return _log_and_return(400, _err("VALIDATION_ERROR", "Invalid filters.event_type"))
                    rows = [e for e in rows if e.get("event_type") == et]
                ca = _parse_dt(filters.get("created_after")) if "created_after" in filters else None
                cb = _parse_dt(filters.get("created_before")) if "created_before" in filters else None
                if "created_after" in filters and ca is None:
                    return _log_and_return(400, _err("VALIDATION_ERROR", "filters.created_after must be ISO 8601 date-time"))
                if "created_before" in filters and cb is None:
                    return _log_and_return(400, _err("VALIDATION_ERROR", "filters.created_before must be ISO 8601 date-time"))
                if ca:
                    rows = [e for e in rows if (_parse_dt(e.get("created_at")) or datetime.datetime.min) > ca]
                if cb:
                    rows = [e for e in rows if (_parse_dt(e.get("created_at")) or datetime.datetime.min) < cb]

            # sort for audit events: created_at/updated_at only (fallback to created_at)
            sort_v = sort or "-created_at"
            if sort_v not in ("created_at", "-created_at", "updated_at", "-updated_at"):
                return _log_and_return(400, _err("VALIDATION_ERROR", "Invalid sort for audit events"))
            key = sort_v.lstrip("-")
            rev = sort_v.startswith("-")
            def k(e):
                return _parse_dt(e.get(key)) or datetime.datetime.min
            rows = sorted(rows, key=k, reverse=rev)
            page, meta, pe = _paginate(rows, cursor, limit)
            if pe:
                return _log_and_return(400, pe)
            return _log_and_return(200, {"data": page, "meta": meta})

        return _log_and_return(400, _err("VALIDATION_ERROR", "Unsupported action"))
    except Exception as e:
        return _log_and_return(500, _err("CONFLICT", "Unexpected error", detail=str(e)))

def Accounts(action, account_id=None, body=None, cursor=None, limit=None, sort=None, filters=None, **_extra):
    import json, os, datetime, re, time, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0129000" if __import__("os").path.isdir("./environment_mix/0129000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")
        return None

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _id(prefix):
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        return prefix + "".join(secrets.choice(alphabet) for _ in range(20))

    def _pick_log_file():
        for fn in ("request_logs.json", "api_requests.json", "request_log.json", "usage.json"):
            if os.path.exists(os.path.join(_DB, fn)):
                return fn
        return None

    def _log_call(status, account_id_used=None, meta=None):
        fn = _pick_log_file()
        if not fn:
            return
        rows = _load(fn)
        if not isinstance(rows, list):
            rows = []
        rows.append({
            "id": _id("cgs_req_"),
            "endpoint": "accounts",
            "tool": "Accounts",
            "status": status,
            "latency_ms": int((time.time() - _t0) * 1000),
            "timestamp": _iso(_now()),
            "account_id": account_id_used,
            "server_id": None,
            "session_id": None,
            "metadata": meta or {}
        })
        _save(fn, rows)

    def _enforce_rate_limit(account_id_used):
        fn = _pick_log_file()
        if not fn or not account_id_used:
            return None
        rows = _load(fn)
        if not isinstance(rows, list):
            return None
        now = _now()
        win_start = now - datetime.timedelta(seconds=60)
        month_start = now.replace(day=1, hour=0, minute=0, second=0)
        per_min = 0
        per_month = 0
        for r in rows:
            if not isinstance(r, dict):
                continue
            if r.get("account_id") != account_id_used:
                continue
            ts = _parse_dt(r.get("timestamp") or r.get("created_at"))
            if not ts:
                continue
            if ts >= win_start:
                per_min += 1
            if ts >= month_start:
                per_month += 1
        if per_min >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded (120 calls/minute).")
        if per_month >= 50000:
            return _err("QUOTA_EXCEEDED", "Monthly quota exceeded (50,000 calls/month).")
        return None

    def _email_ok(e):
        if not isinstance(e, str) or not e or len(e) > 320:
            return False
        return re.match(r"^[^@\s]+@[^@\s]+\.[^@\s]+$", e) is not None

    def _scrub(acc):
        if not isinstance(acc, dict):
            return acc
        out = dict(acc)
        out.pop("password_hash", None)
        return out

    def _sort_rows(rows, sort_key):
        if not sort_key:
            sort_key = "created_at"
        desc = sort_key.startswith("-")
        key = sort_key[1:] if desc else sort_key

        def kf(r):
            v = r.get(key)
            if key.endswith("_at"):
                dt = _parse_dt(v) if isinstance(v, str) else None
                return dt or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
            return v if v is not None else ""
        return sorted(rows, key=kf, reverse=desc)

    def _list_paginate(rows, cursor_v, limit_v):
        start = 0
        if cursor_v:
            for i, r in enumerate(rows):
                if isinstance(r, dict) and r.get("id") == cursor_v:
                    start = i + 1
                    break
        lim = limit_v if isinstance(limit_v, int) else 50
        page = rows[start:start + lim]
        has_more = start + lim < len(rows)
        next_cursor = page[-1].get("id") if has_more and page and isinstance(page[-1], dict) else None
        return page, len(rows), has_more, next_cursor

    # validate request
    try:
        if not isinstance(action, str):
            _log_call("error", meta={"error": "action_type"})
            return _err("VALIDATION_ERROR", "action must be a string.")
        if action not in ("create", "update", "get", "list", "suspend", "reactivate", "delete"):
            _log_call("error", meta={"error": "invalid_action"})
            return _err("VALIDATION_ERROR", "Invalid action.")
        if account_id is not None and (not isinstance(account_id, str) or re.match(r"^cgs_acct_[0-9A-Z]{18,}$", account_id) is None):
            _log_call("error", account_id_used=account_id, meta={"error": "invalid_account_id"})
            return _err("VALIDATION_ERROR", "Invalid account_id format.")
        if limit is not None and (not isinstance(limit, int) or limit < 1 or limit > 200):
            _log_call("error", meta={"error": "invalid_limit"})
            return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.")
        if sort is not None and sort not in ("created_at", "-created_at", "updated_at", "-updated_at", "last_login_at", "-last_login_at"):
            _log_call("error", meta={"error": "invalid_sort"})
            return _err("VALIDATION_ERROR", "Invalid sort.")
        if filters is not None and not isinstance(filters, dict):
            _log_call("error", meta={"error": "invalid_filters"})
            return _err("VALIDATION_ERROR", "filters must be an object.")
        if body is not None and not isinstance(body, dict):
            _log_call("error", meta={"error": "invalid_body"})
            return _err("VALIDATION_ERROR", "body must be an object.")
    except Exception as e:
        _log_call("error", meta={"error": "validation_exception", "detail": str(e)})
        return _err("VALIDATION_ERROR", "Invalid request.")

    accounts = _load("accounts.json")

    # ambient account for rate limits: choose provided account_id if present, else first active account
    ambient_account_id = None
    if account_id:
        ambient_account_id = account_id
    else:
        for a in accounts:
            if isinstance(a, dict) and a.get("status") == "active" and isinstance(a.get("id"), str):
                ambient_account_id = a.get("id")
                break
        if ambient_account_id is None and accounts and isinstance(accounts[0], dict):
            ambient_account_id = accounts[0].get("id")

    rl = _enforce_rate_limit(ambient_account_id)
    if rl:
        _log_call("error", account_id_used=ambient_account_id, meta={"error": "rate_limited"})
        return rl

    # actions
    try:
        if action == "get":
            if not account_id:
                _log_call("error", meta={"error": "missing_account_id"})
                return _err("VALIDATION_ERROR", "account_id is required for get.")
            for a in accounts:
                if isinstance(a, dict) and a.get("id") == account_id:
                    _log_call("success", account_id_used=account_id)
                    return {"data": _scrub(a), "meta": {}}
            _log_call("error", account_id_used=account_id, meta={"error": "not_found"})
            return _err("NOT_FOUND", "Account not found.")

        if action == "list":
            rows = [a for a in accounts if isinstance(a, dict) and isinstance(a.get("id"), str)]
            if filters:
                st = filters.get("status")
                em = filters.get("email")
                if st is not None:
                    rows = [a for a in rows if a.get("status") == st]
                if em is not None:
                    rows = [a for a in rows if a.get("email") == em]
                ca = filters.get("created_after")
                cb = filters.get("created_before")
                ca_dt = _parse_dt(ca) if ca else None
                cb_dt = _parse_dt(cb) if cb else None
                if (ca and ca_dt is None) or (cb and cb_dt is None):
                    _log_call("error", account_id_used=ambient_account_id, meta={"error": "invalid_time_filter"})
                    return _err("VALIDATION_ERROR", "Invalid date-time filter; must be ISO 8601.")
                if ca_dt or cb_dt:
                    filtered = []
                    for a in rows:
                        dt = _parse_dt(a.get("created_at")) if isinstance(a.get("created_at"), str) else None
                        if not dt:
                            continue
                        if ca_dt and dt <= ca_dt:
                            continue
                        if cb_dt and dt >= cb_dt:
                            continue
                        filtered.append(a)
                    rows = filtered
            rows = _sort_rows(rows, sort or "created_at")
            page, total, has_more, next_cursor = _list_paginate(rows, cursor, limit)
            page = [_scrub(a) for a in page]
            _log_call("success", account_id_used=ambient_account_id, meta={"count": len(page), "total": total})
            return {"data": page, "meta": {"total": total, "has_more": has_more, "next_cursor": next_cursor}}

        if action == "create":
            if body is None:
                _log_call("error", account_id_used=ambient_account_id, meta={"error": "missing_body"})
                return _err("VALIDATION_ERROR", "body is required for create.")
            email = body.get("email")
            auth_provider = body.get("auth_provider")
            if not _email_ok(email):
                _log_call("error", meta={"error": "invalid_email"})
                return _err("VALIDATION_ERROR", "email must be non-empty and syntactically valid.")
            if auth_provider not in ("local", "oauth", "sso"):
                _log_call("error", meta={"error": "invalid_auth_provider"})
                return _err("VALIDATION_ERROR", "auth_provider must be one of ('local','oauth','sso').")
            # unique(email)
            for a in accounts:
                if isinstance(a, dict) and a.get("email") == email:
                    _log_call("error", meta={"error": "email_conflict"})
                    return _err("CONFLICT", "Email already exists.")
            ts = _iso(_now())
            new_id = _id("cgs_acct_")
            # allow caller-provided account_id but enforce uniqueness and format if provided
            if account_id is not None:
                if re.match(r"^cgs_acct_[0-9A-Z]{18,}$", account_id) is None:
                    _log_call("error", meta={"error": "invalid_account_id"})
                    return _err("VALIDATION_ERROR", "Invalid account_id format.")
                for a in accounts:
                    if isinstance(a, dict) and a.get("id") == account_id:
                        _log_call("error", account_id_used=account_id, meta={"error": "id_conflict"})
                        return _err("CONFLICT", "Account id already exists.")
                new_id = account_id
            new_row = {
                "id": new_id,
                "email": email,
                "display_name": body.get("display_name"),
                "password_hash": body.get("password") if isinstance(body.get("password"), str) else None,
                "auth_provider": auth_provider,
                "status": "active",
                "last_login_at": None,
                "created_at": ts,
                "updated_at": ts
            }
            accounts.append(new_row)
            _save("accounts.json", accounts)
            _log_call("success", account_id_used=new_id, meta={"created": new_id})
            return {"data": _scrub(new_row), "meta": {}}

        # find target for mutations
        if not account_id:
            _log_call("error", meta={"error": "missing_account_id"})
            return _err("VALIDATION_ERROR", "account_id is required for this action.")
        target = None
        for a in accounts:
            if isinstance(a, dict) and a.get("id") == account_id:
                target = a
                break
        if not target:
            _log_call("error", account_id_used=account_id, meta={"error": "not_found"})
            return _err("NOT_FOUND", "Account not found.")

        def _transition(new_status):
            old = target.get("status")
            allowed = {"active": {"suspended", "deleted"}, "suspended": {"active", "deleted"}, "deleted": set()}
            if old not in allowed or new_status not in allowed[old]:
                return _err("INVALID_TRANSITION", f"Invalid status transition from '{old}' to '{new_status}'.")
            target["status"] = new_status
            target["updated_at"] = _iso(_now())
            return None

        if action == "update":
            if body is None:
                _log_call("error", account_id_used=account_id, meta={"error": "missing_body"})
                return _err("VALIDATION_ERROR", "body is required for update.")
            if "email" in body:
                email = body.get("email")
                if not _email_ok(email):
                    _log_call("error", account_id_used=account_id, meta={"error": "invalid_email"})
                    return _err("VALIDATION_ERROR", "email must be non-empty and syntactically valid.")
                for a in accounts:
                    if isinstance(a, dict) and a.get("email") == email and a.get("id") != account_id:
                        _log_call("error", account_id_used=account_id, meta={"error": "email_conflict"})
                        return _err("CONFLICT", "Email already exists.")
                target["email"] = email
            if "display_name" in body:
                target["display_name"] = body.get("display_name")
            if "password" in body:
                target["password_hash"] = body.get("password") if isinstance(body.get("password"), str) else None
            if "auth_provider" in body:
                ap = body.get("auth_provider")
                if ap not in ("local", "oauth", "sso"):
                    _log_call("error", account_id_used=account_id, meta={"error": "invalid_auth_provider"})
                    return _err("VALIDATION_ERROR", "auth_provider must be one of ('local','oauth','sso').")
                target["auth_provider"] = ap
            if "status" in body:
                st = body.get("status")
                if st not in ("active", "suspended", "deleted"):
                    _log_call("error", account_id_used=account_id, meta={"error": "status_enum"})
                    return _err("VALIDATION_ERROR", "status must be one of ('active','suspended','deleted').")
                # status should be transitioned via actions; but allow if it's a legal transition
                terr = _transition(st)
                if terr:
                    _log_call("error", account_id_used=account_id, meta={"error": "invalid_transition"})
                    return terr
            target["updated_at"] = _iso(_now())
            _save("accounts.json", accounts)
            _log_call("success", account_id_used=account_id, meta={"updated": True})
            return {"data": _scrub(target), "meta": {}}

        if action == "suspend":
            terr = _transition("suspended")
            if terr:
                _log_call("error", account_id_used=account_id, meta={"error": "invalid_transition"})
                return terr
            _save("accounts.json", accounts)
            _log_call("success", account_id_used=account_id, meta={"status": "suspended"})
            return {"data": _scrub(target), "meta": {}}

        if action == "reactivate":
            terr = _transition("active")
            if terr:
                _log_call("error", account_id_used=account_id, meta={"error": "invalid_transition"})
                return terr
            _save("accounts.json", accounts)
            _log_call("success", account_id_used=account_id, meta={"status": "active"})
            return {"data": _scrub(target), "meta": {}}

        if action == "delete":
            terr = _transition("deleted")
            if terr:
                _log_call("error", account_id_used=account_id, meta={"error": "invalid_transition"})
                return terr
            _save("accounts.json", accounts)
            _log_call("success", account_id_used=account_id, meta={"status": "deleted"})
            return {"data": _scrub(target), "meta": {}}

        _log_call("error", account_id_used=account_id, meta={"error": "unhandled_action"})
        return _err("VALIDATION_ERROR", "Unhandled action.")
    except Exception as e:
        _log_call("error", account_id_used=ambient_account_id, meta={"error": "exception", "detail": str(e)})
        return _err("VALIDATION_ERROR", "Request failed unexpectedly.", detail=str(e))

def Servers(action, server_id=None, body=None, cursor=None, limit=None, sort=None, filters=None, **_extra):
    import json, os, datetime, re, time, secrets, urllib.parse

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0129000" if __import__("os").path.isdir("./environment_mix/0129000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")
        return None

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _id(prefix):
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        return prefix + "".join(secrets.choice(alphabet) for _ in range(20))

    def _pick_log_file():
        for fn in ("request_logs.json", "api_requests.json", "request_log.json", "usage.json"):
            if os.path.exists(os.path.join(_DB, fn)):
                return fn
        return None

    def _log_call(status, server_id_used=None, meta=None):
        fn = _pick_log_file()
        if not fn:
            return
        rows = _load(fn)
        if not isinstance(rows, list):
            rows = []
        rows.append({
            "id": _id("cgs_req_"),
            "endpoint": "servers",
            "tool": "Servers",
            "status": status,
            "latency_ms": int((time.time() - _t0) * 1000),
            "timestamp": _iso(_now()),
            "account_id": None,
            "server_id": server_id_used,
            "session_id": None,
            "metadata": meta or {}
        })
        _save(fn, rows)

    def _enforce_rate_limit():
        fn = _pick_log_file()
        if not fn:
            return None
        rows = _load(fn)
        if not isinstance(rows, list):
            return None
        now = _now()
        win_start = now - datetime.timedelta(seconds=60)
        per_min = 0
        for r in rows:
            if not isinstance(r, dict):
                continue
            ts = _parse_dt(r.get("timestamp") or r.get("created_at"))
            if ts and ts >= win_start:
                per_min += 1
        if per_min >= 300:
            return _err("RATE_LIMIT", "Rate limit exceeded (300 calls/minute).")
        return None

    def _url_ok(u, env):
        if not isinstance(u, str) or not u:
            return False, "base_url must be a valid URL."
        try:
            pr = urllib.parse.urlparse(u)
        except Exception:
            return False, "base_url must be a valid URL."
        if pr.scheme not in ("http", "https") or not pr.netloc:
            return False, "base_url must be a valid URL."
        if env in ("production", "staging"):
            if pr.scheme != "https":
                return False, "base_url must use https except in development/custom environments."
        return True, None

    def _sort_rows(rows, sort_key):
        if not sort_key:
            sort_key = "created_at"
        desc = sort_key.startswith("-")
        key = sort_key[1:] if desc else sort_key

        def kf(r):
            v = r.get(key)
            if key.endswith("_at"):
                dt = _parse_dt(v) if isinstance(v, str) else None
                return dt or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
            return v if v is not None else ""
        return sorted(rows, key=kf, reverse=desc)

    def _list_paginate(rows, cursor_v, limit_v):
        start = 0
        if cursor_v:
            for i, r in enumerate(rows):
                if isinstance(r, dict) and r.get("id") == cursor_v:
                    start = i + 1
                    break
        lim = limit_v if isinstance(limit_v, int) else 50
        page = rows[start:start + lim]
        has_more = start + lim < len(rows)
        next_cursor = page[-1].get("id") if has_more and page and isinstance(page[-1], dict) else None
        return page, len(rows), has_more, next_cursor

    # validate
    try:
        if not isinstance(action, str):
            _log_call("error", meta={"error": "action_type"})
            return _err("VALIDATION_ERROR", "action must be a string.")
        if action not in ("create", "update", "get", "list", "enable", "disable", "delete"):
            _log_call("error", meta={"error": "invalid_action"})
            return _err("VALIDATION_ERROR", "Invalid action.")
        if server_id is not None and (not isinstance(server_id, str) or re.match(r"^cgs_srv_[0-9A-Z]{18,}$", server_id) is None):
            _log_call("error", server_id_used=server_id, meta={"error": "invalid_server_id"})
            return _err("VALIDATION_ERROR", "Invalid server_id format.")
        if limit is not None and (not isinstance(limit, int) or limit < 1 or limit > 200):
            _log_call("error", meta={"error": "invalid_limit"})
            return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.")
        if sort is not None and sort not in ("created_at", "-created_at", "updated_at", "-updated_at"):
            _log_call("error", meta={"error": "invalid_sort"})
            return _err("VALIDATION_ERROR", "Invalid sort.")
        if filters is not None and not isinstance(filters, dict):
            _log_call("error", meta={"error": "invalid_filters"})
            return _err("VALIDATION_ERROR", "filters must be an object.")
        if body is not None and not isinstance(body, dict):
            _log_call("error", meta={"error": "invalid_body"})
            return _err("VALIDATION_ERROR", "body must be an object.")
    except Exception as e:
        _log_call("error", meta={"error": "validation_exception", "detail": str(e)})
        return _err("VALIDATION_ERROR", "Invalid request.")

    rl = _enforce_rate_limit()
    if rl:
        _log_call("error", server_id_used=server_id, meta={"error": "rate_limited"})
        return rl

    servers = _load("servers.json")

    # actions
    try:
        if action == "get":
            if not server_id:
                _log_call("error", meta={"error": "missing_server_id"})
                return _err("VALIDATION_ERROR", "server_id is required for get.")
            for s in servers:
                if isinstance(s, dict) and s.get("id") == server_id:
                    _log_call("success", server_id_used=server_id)
                    return {"data": s, "meta": {}}
            _log_call("error", server_id_used=server_id, meta={"error": "not_found"})
            return _err("NOT_FOUND", "Server not found.")

        if action == "list":
            rows = [s for s in servers if isinstance(s, dict) and isinstance(s.get("id"), str)]
            if filters:
                st = filters.get("status")
                env = filters.get("environment")
                bu = filters.get("base_url")
                if st is not None:
                    rows = [s for s in rows if s.get("status") == st]
                if env is not None:
                    rows = [s for s in rows if s.get("environment") == env]
                if bu is not None:
                    rows = [s for s in rows if s.get("base_url") == bu]
                ca = filters.get("created_after")
                cb = filters.get("created_before")
                ca_dt = _parse_dt(ca) if ca else None
                cb_dt = _parse_dt(cb) if cb else None
                if (ca and ca_dt is None) or (cb and cb_dt is None):
                    _log_call("error", meta={"error": "invalid_time_filter"})
                    return _err("VALIDATION_ERROR", "Invalid date-time filter; must be ISO 8601.")
                if ca_dt or cb_dt:
                    filtered = []
                    for s in rows:
                        dt = _parse_dt(s.get("created_at")) if isinstance(s.get("created_at"), str) else None
                        if not dt:
                            continue
                        if ca_dt and dt <= ca_dt:
                            continue
                        if cb_dt and dt >= cb_dt:
                            continue
                        filtered.append(s)
                    rows = filtered
            rows = _sort_rows(rows, sort or "created_at")
            page, total, has_more, next_cursor = _list_paginate(rows, cursor, limit)
            _log_call("success", meta={"count": len(page), "total": total})
            return {"data": page, "meta": {"total": total, "has_more": has_more, "next_cursor": next_cursor}}

        if action == "create":
            if body is None:
                _log_call("error", meta={"error": "missing_body"})
                return _err("VALIDATION_ERROR", "body is required for create.")
            name = body.get("name")
            base_url = body.get("base_url")
            env = body.get("environment")
            status = body.get("status", "active")
            if not isinstance(name, str) or not name.strip():
                _log_call("error", meta={"error": "name_required"})
                return _err("VALIDATION_ERROR", "name is required.")
            if env not in ("production", "staging", "development", "custom"):
                _log_call("error", meta={"error": "invalid_environment"})
                return _err("VALIDATION_ERROR", "environment must be one of ('production','staging','development','custom').")
            ok, msg = _url_ok(base_url, env)
            if not ok:
                _log_call("error", meta={"error": "invalid_base_url"})
                return _err("VALIDATION_ERROR", msg)
            if status not in ("active", "disabled", "deleted"):
                _log_call("error", meta={"error": "invalid_status"})
                return _err("VALIDATION_ERROR", "status must be one of ('active','disabled','deleted').")
            for s in servers:
                if isinstance(s, dict) and s.get("base_url") == base_url:
                    _log_call("error", meta={"error": "base_url_conflict"})
                    return _err("CONFLICT", "base_url already exists.")
            ts = _iso(_now())
            new_id = _id("cgs_srv_")
            if server_id is not None:
                if re.match(r"^cgs_srv_[0-9A-Z]{18,}$", server_id) is None:
                    _log_call("error", server_id_used=server_id, meta={"error": "invalid_server_id"})
                    return _err("VALIDATION_ERROR", "Invalid server_id format.")
                for s in servers:
                    if isinstance(s, dict) and s.get("id") == server_id:
                        _log_call("error", server_id_used=server_id, meta={"error": "id_conflict"})
                        return _err("CONFLICT", "Server id already exists.")
                new_id = server_id
            new_row = {
                "id": new_id,
                "name": name,
                "base_url": base_url,
                "environment": env,
                "status": status,
                "created_at": ts,
                "updated_at": ts
            }
            servers.append(new_row)
            _save("servers.json", servers)
            _log_call("success", server_id_used=new_id, meta={"created": new_id})
            return {"data": new_row, "meta": {}}

        if not server_id:
            _log_call("error", meta={"error": "missing_server_id"})
            return _err("VALIDATION_ERROR", "server_id is required for this action.")
        target = None
        for s in servers:
            if isinstance(s, dict) and s.get("id") == server_id:
                target = s
                break
        if not target:
            _log_call("error", server_id_used=server_id, meta={"error": "not_found"})
            return _err("NOT_FOUND", "Server not found.")

        def _transition(new_status):
            old = target.get("status")
            allowed = {"active": {"disabled", "deleted"}, "disabled": {"active", "deleted"}, "deleted": set()}
            if old not in allowed or new_status not in allowed[old]:
                return _err("INVALID_TRANSITION", f"Invalid status transition from '{old}' to '{new_status}'.")
            target["status"] = new_status
            target["updated_at"] = _iso(_now())
            return None

        if action == "update":
            if body is None:
                _log_call("error", server_id_used=server_id, meta={"error": "missing_body"})
                return _err("VALIDATION_ERROR", "body is required for update.")
            if "name" in body:
                nm = body.get("name")
                if not isinstance(nm, str) or not nm.strip():
                    _log_call("error", server_id_used=server_id, meta={"error": "name_required"})
                    return _err("VALIDATION_ERROR", "name must be non-empty.")
                target["name"] = nm
            # base_url/environment interdependence
            env = target.get("environment")
            if "environment" in body:
                env2 = body.get("environment")
                if env2 not in ("production", "staging", "development", "custom"):
                    _log_call("error", server_id_used=server_id, meta={"error": "invalid_environment"})
                    return _err("VALIDATION_ERROR", "environment must be one of ('production','staging','development','custom').")
                env = env2
                target["environment"] = env2
            if "base_url" in body:
                bu = body.get("base_url")
                ok, msg = _url_ok(bu, env)
                if not ok:
                    _log_call("error", server_id_used=server_id, meta={"error": "invalid_base_url"})
                    return _err("VALIDATION_ERROR", msg)
                for s in servers:
                    if isinstance(s, dict) and s.get("base_url") == bu and s.get("id") != server_id:
                        _log_call("error", server_id_used=server_id, meta={"error": "base_url_conflict"})
                        return _err("CONFLICT", "base_url already exists.")
                target["base_url"] = bu
            if "status" in body:
                st = body.get("status")
                if st not in ("active", "disabled", "deleted"):
                    _log_call("error", server_id_used=server_id, meta={"error": "invalid_status"})
                    return _err("VALIDATION_ERROR", "status must be one of ('active','disabled','deleted').")
                terr = _transition(st)
                if terr:
                    _log_call("error", server_id_used=server_id, meta={"error": "invalid_transition"})
                    return terr
            target["updated_at"] = _iso(_now())
            _save("servers.json", servers)
            _log_call("success", server_id_used=server_id, meta={"updated": True})
            return {"data": target, "meta": {}}

        if action == "enable":
            if target.get("status") == "active":
                _log_call("success", server_id_used=server_id, meta={"idempotent": True})
                return {"data": target, "meta": {"idempotent": True}}
            terr = _transition("active")
            if terr:
                _log_call("error", server_id_used=server_id, meta={"error": "invalid_transition"})
                return terr
            _save("servers.json", servers)
            _log_call("success", server_id_used=server_id, meta={"status": "active"})
            return {"data": target, "meta": {}}

        if action == "disable":
            if target.get("status") == "disabled":
                _log_call("success", server_id_used=server_id, meta={"idempotent": True})
                return {"data": target, "meta": {"idempotent": True}}
            terr = _transition("disabled")
            if terr:
                _log_call("error", server_id_used=server_id, meta={"error": "invalid_transition"})
                return terr
            _save("servers.json", servers)
            _log_call("success", server_id_used=server_id, meta={"status": "disabled"})
            return {"data": target, "meta": {}}

        if action == "delete":
            if target.get("status") == "deleted":
                _log_call("success", server_id_used=server_id, meta={"idempotent": True})
                return {"data": target, "meta": {"idempotent": True}}
            terr = _transition("deleted")
            if terr:
                _log_call("error", server_id_used=server_id, meta={"error": "invalid_transition"})
                return terr
            _save("servers.json", servers)
            _log_call("success", server_id_used=server_id, meta={"status": "deleted"})
            return {"data": target, "meta": {}}

        _log_call("error", server_id_used=server_id, meta={"error": "unhandled_action"})
        return _err("VALIDATION_ERROR", "Unhandled action.")
    except Exception as e:
        _log_call("error", server_id_used=server_id, meta={"error": "exception", "detail": str(e)})
        return _err("VALIDATION_ERROR", "Request failed unexpectedly.", detail=str(e))

def Auth_Sessions(action, session_id=None, server_id=None, cursor=None, limit=None, sort=None, filters=None, **_extra):
    import json, os, datetime, time, re, base64, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0129000" if __import__("os").path.isdir("./environment_mix/0129000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now.isoformat()

    # --- request log / rate limiting (best-effort; schema may not have a log collection) ---
    def _log(endpoint, status, account_id=None, server_id=None, session_id=None, detail=None, latency_ms=None):
        # Try common filenames for request logs / usage.
        candidates = ["request_logs.json", "usage.json", "api_requests.json", "request_log.json"]
        existing = None
        for fn in candidates:
            path = os.path.join(_DB, fn)
            if os.path.exists(path):
                existing = fn
                break
        if existing is None:
            return
        rows = _load(existing)
        if not isinstance(rows, list):
            rows = []
        rid = "cgs_req_" + base64.b32encode(os.urandom(12)).decode("ascii").rstrip("=")
        row = {
            "id": rid,
            "endpoint": endpoint,
            "status": status,
            "account_id": account_id,
            "server_id": server_id,
            "session_id": session_id,
            "detail": detail or {},
            "latency_ms": int(latency_ms if latency_ms is not None else (time.time() - _t0) * 1000),
            "created_at": now_iso,
        }
        rows.append(row)
        _save(existing, rows)

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            # Accept Z suffix
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _dt_from_row(v):
        if v is None:
            return None
        if isinstance(v, (int, float)):
            try:
                return datetime.datetime.fromtimestamp(v, tz=datetime.timezone.utc)
            except Exception:
                return None
        if isinstance(v, str):
            return _parse_dt(v)
        return None

    def _gen_id(prefix):
        # 18+ base32 chars, uppercase
        return prefix + base64.b32encode(os.urandom(14)).decode("ascii").rstrip("=")

    def _is_valid_id(pat, val):
        if val is None:
            return True
        if not isinstance(val, str):
            return False
        return re.match(pat, val) is not None

    # --- input validation ---
    if not isinstance(action, str) or action not in ("get", "list", "refresh", "revoke"):
        _log("auth_sessions", "error", detail={"error": "invalid_action"})
        return _err("VALIDATION_ERROR", "Invalid action.")
    if not _is_valid_id(r"^cgs_sess_[0-9A-Z]{18,}$", session_id) and session_id is not None:
        _log("auth_sessions", "error", detail={"error": "invalid_session_id"})
        return _err("VALIDATION_ERROR", "Invalid session_id format.")
    if not _is_valid_id(r"^cgs_srv_[0-9A-Z]{18,}$", server_id) and server_id is not None:
        _log("auth_sessions", "error", detail={"error": "invalid_server_id"})
        return _err("VALIDATION_ERROR", "Invalid server_id format.")
    if limit is None:
        limit = 50 if action == "list" else None
    if limit is not None:
        if not isinstance(limit, int):
            _log("auth_sessions", "error", detail={"error": "limit_type"})
            return _err("VALIDATION_ERROR", "limit must be an integer.")
        if limit < 1 or limit > 200:
            _log("auth_sessions", "error", detail={"error": "limit_range"})
            return _err("VALIDATION_ERROR", "limit must be between 1 and 200.")
    if sort is None and action == "list":
        sort = "-created_at"
    if sort is not None:
        if not isinstance(sort, str) or sort not in ("created_at", "-created_at", "updated_at", "-updated_at", "last_used_at", "-last_used_at", "expires_at", "-expires_at"):
            _log("auth_sessions", "error", detail={"error": "invalid_sort"})
            return _err("VALIDATION_ERROR", "Invalid sort value.")
    if cursor is not None and not isinstance(cursor, str):
        _log("auth_sessions", "error", detail={"error": "cursor_type"})
        return _err("VALIDATION_ERROR", "cursor must be a string.")
    if filters is not None and not isinstance(filters, dict):
        _log("auth_sessions", "error", detail={"error": "filters_type"})
        return _err("VALIDATION_ERROR", "filters must be an object.")
    if isinstance(filters, dict):
        allowed = {"status", "created_after", "created_before", "expires_before", "expires_after"}
        for k in filters.keys():
            if k not in allowed:
                _log("auth_sessions", "error", detail={"error": "filters_extra", "field": k})
                return _err("VALIDATION_ERROR", "filters contains an unknown field.", field=k)
        if "status" in filters and filters["status"] is not None:
            if filters["status"] not in ("active", "expired", "revoked"):
                _log("auth_sessions", "error", detail={"error": "filters_status"})
                return _err("VALIDATION_ERROR", "Invalid filters.status.")
        for k in ("created_after", "created_before", "expires_before", "expires_after"):
            if k in filters and filters[k] is not None:
                if _parse_dt(filters[k]) is None:
                    _log("auth_sessions", "error", detail={"error": "filters_dt", "field": k})
                    return _err("VALIDATION_ERROR", f"Invalid {k} timestamp; must be ISO 8601 date-time.", field=k)

    # --- ambient authentication resolution ---
    accounts = _load("accounts.json")
    servers = _load("servers.json")
    sessions = _load("auth_sessions.json")
    settings = _load("optional_settings.json")
    audit = _load("audit_events.json")

    # Choose an authenticated active account and a usable server for context.
    def _pick_context():
        # Prefer account with an existing session; else any active account.
        active_accounts = [a for a in accounts if isinstance(a, dict) and a.get("status") == "active" and isinstance(a.get("id"), str)]
        if not active_accounts:
            return None, None
        # prefer account that has any session
        acct_ids_with_sessions = set([s.get("account_id") for s in sessions if isinstance(s, dict) and isinstance(s.get("account_id"), str)])
        preferred = None
        for a in active_accounts:
            if a["id"] in acct_ids_with_sessions:
                preferred = a
                break
        if preferred is None:
            preferred = active_accounts[0]

        usable_servers = [sv for sv in servers if isinstance(sv, dict) and sv.get("status") == "active" and isinstance(sv.get("id"), str)]
        if not usable_servers:
            # still allow list/get that doesn't require creating/enabling, but context server may be None
            return preferred, None
        # prefer server used in any session for that account
        used_srv_ids = set([s.get("server_id") for s in sessions if isinstance(s, dict) and s.get("account_id") == preferred["id"]])
        for sv in usable_servers:
            if sv["id"] in used_srv_ids:
                return preferred, sv
        return preferred, usable_servers[0]

    account = None
    default_server = None
    account, default_server = _pick_context()
    if account is None:
        _log("auth_sessions", "unauthorized")
        return _err("UNAUTHORIZED", "Authentication missing or invalid.")

    # If caller supplies server_id, it must exist; for list it can filter to none (empty ok).
    server_row = None
    if server_id is not None:
        server_row = next((sv for sv in servers if isinstance(sv, dict) and sv.get("id") == server_id), None)
        if server_row is None:
            _log("auth_sessions", "error", account_id=account["id"], server_id=server_id, detail={"error": "server_not_found"})
            return _err("NOT_FOUND", "Server not found.")
    else:
        server_row = default_server

    # --- quota/rate limit enforcement (if request log exists) ---
    # Implement a simple per-account 60 req/min and 10k req/day when request log collection is present.
    def _enforce_limits():
        candidates = ["request_logs.json", "usage.json", "api_requests.json", "request_log.json"]
        existing = None
        for fn in candidates:
            if os.path.exists(os.path.join(_DB, fn)):
                existing = fn
                break
        if existing is None:
            return None
        rows = _load(existing)
        if not isinstance(rows, list):
            return None
        acct_id = account["id"]
        one_min_ago = now - datetime.timedelta(seconds=60)
        day_ago = now - datetime.timedelta(days=1)
        m = 0
        d = 0
        for r in rows:
            if not isinstance(r, dict):
                continue
            if r.get("account_id") != acct_id:
                continue
            t = _parse_dt(r.get("created_at")) if isinstance(r.get("created_at"), str) else None
            if t is None:
                continue
            if t >= one_min_ago:
                m += 1
            if t >= day_ago:
                d += 1
        if m >= 60:
            return _err("RATE_LIMIT", "Rate limit exceeded.", limit="60/min", window_seconds=60)
        if d >= 10000:
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded.", limit="10000/day", window_seconds=86400)
        return None

    limerr = _enforce_limits()
    if limerr:
        _log("auth_sessions", "rate_limited", account_id=account["id"], server_id=(server_row.get("id") if server_row else None))
        return limerr

    # --- helpers for audit ---
    def _audit(event_type, account_id=None, server_id=None, session_id=None, metadata=None):
        if metadata is None or not isinstance(metadata, dict):
            metadata = {}
        aid = _gen_id("cgs_aud_")
        row = {
            "id": aid,
            "account_id": account_id,
            "server_id": server_id,
            "session_id": session_id,
            "event_type": event_type,
            "ip_address": None,
            "user_agent": None,
            "metadata": metadata,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        audit.append(row)

    # --- operations ---
    if action == "get":
        if session_id is None:
            _log("auth_sessions", "error", account_id=account["id"], detail={"error": "missing_session_id"})
            return _err("VALIDATION_ERROR", "session_id is required for action='get'.")
        sess = next((s for s in sessions if isinstance(s, dict) and s.get("id") == session_id and s.get("account_id") == account["id"]), None)
        if sess is None:
            _log("auth_sessions", "not_found", account_id=account["id"], session_id=session_id)
            return _err("NOT_FOUND", "Session not found.")
        _log("auth_sessions", "ok", account_id=account["id"], server_id=sess.get("server_id"), session_id=sess.get("id"))
        return {"data": sess}

    if action == "list":
        # Filter only authenticated account
        rows = [s for s in sessions if isinstance(s, dict) and s.get("account_id") == account["id"]]
        if server_id is not None:
            rows = [s for s in rows if s.get("server_id") == server_id]
        if isinstance(filters, dict):
            st = filters.get("status")
            if st is not None:
                rows = [s for s in rows if s.get("status") == st]
            ca = _parse_dt(filters.get("created_after")) if filters.get("created_after") is not None else None
            cb = _parse_dt(filters.get("created_before")) if filters.get("created_before") is not None else None
            ea = _parse_dt(filters.get("expires_after")) if filters.get("expires_after") is not None else None
            eb = _parse_dt(filters.get("expires_before")) if filters.get("expires_before") is not None else None

            if ca is not None:
                rows = [s for s in rows if (_dt_from_row(s.get("created_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)) > ca]
            if cb is not None:
                rows = [s for s in rows if (_dt_from_row(s.get("created_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)) < cb]
            if ea is not None:
                rows = [s for s in rows if (_dt_from_row(s.get("expires_at")) or datetime.datetime.max.replace(tzinfo=datetime.timezone.utc)) > ea]
            if eb is not None:
                rows = [s for s in rows if (_dt_from_row(s.get("expires_at")) or datetime.datetime.max.replace(tzinfo=datetime.timezone.utc)) < eb]

        key = sort.lstrip("-")
        desc = sort.startswith("-")

        def _sort_key(s):
            v = s.get(key)
            dtv = _dt_from_row(v)
            if dtv is not None:
                return dtv
            if v is None:
                return datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
            return v

        try:
            rows.sort(key=_sort_key, reverse=desc)
        except Exception:
            # If mixed types break sorting, fall back to created_at string
            rows.sort(key=lambda s: str(s.get(key, "")), reverse=desc)

        # Cursor: base64 of last id; simplistic but stable
        start = 0
        if cursor:
            try:
                raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
                last_id = raw.decode("utf-8")
                for i, r in enumerate(rows):
                    if r.get("id") == last_id:
                        start = i + 1
                        break
            except Exception:
                _log("auth_sessions", "error", account_id=account["id"], detail={"error": "bad_cursor"})
                return _err("VALIDATION_ERROR", "Invalid cursor.")

        page = rows[start:start + limit]
        has_more = start + limit < len(rows)
        next_cursor = None
        if has_more and page:
            next_cursor = base64.urlsafe_b64encode(page[-1].get("id", "").encode("utf-8")).decode("utf-8").rstrip("=")

        _log("auth_sessions", "ok", account_id=account["id"], server_id=(server_id or None))
        return {"data": page, "meta": {"total": len(rows), "limit": limit, "has_more": has_more, "next_cursor": next_cursor}}

    if action == "refresh":
        if session_id is None:
            _log("auth_sessions", "error", account_id=account["id"], detail={"error": "missing_session_id"})
            return _err("VALIDATION_ERROR", "session_id is required for action='refresh'.")
        sess = next((s for s in sessions if isinstance(s, dict) and s.get("id") == session_id and s.get("account_id") == account["id"]), None)
        if sess is None:
            _log("auth_sessions", "not_found", account_id=account["id"], session_id=session_id)
            return _err("NOT_FOUND", "Session not found.")
        if sess.get("status") != "active":
            _log("auth_sessions", "invalid_transition", account_id=account["id"], session_id=session_id)
            return _err("INVALID_TRANSITION", "Token refresh is only allowed for active sessions.")
        # Update expiry and last_used_at
        new_exp = now + datetime.timedelta(hours=1)
        sess["expires_at"] = new_exp.isoformat()
        sess["last_used_at"] = now_iso
        sess["updated_at"] = now_iso

        _audit("auth.token_refreshed", account_id=account["id"], server_id=sess.get("server_id"), session_id=sess.get("id"),
               metadata={"changed_fields": ["expires_at", "last_used_at", "updated_at"]})

        _save("auth_sessions.json", sessions)
        _save("audit_events.json", audit)

        _log("auth_sessions", "ok", account_id=account["id"], server_id=sess.get("server_id"), session_id=sess.get("id"))
        return {"data": sess}

    if action == "revoke":
        if session_id is None:
            _log("auth_sessions", "error", account_id=account["id"], detail={"error": "missing_session_id"})
            return _err("VALIDATION_ERROR", "session_id is required for action='revoke'.")
        sess = next((s for s in sessions if isinstance(s, dict) and s.get("id") == session_id and s.get("account_id") == account["id"]), None)
        if sess is None:
            _log("auth_sessions", "not_found", account_id=account["id"], session_id=session_id)
            return _err("NOT_FOUND", "Session not found.")
        if sess.get("status") == "revoked":
            # Idempotent revoke
            _log("auth_sessions", "ok", account_id=account["id"], server_id=sess.get("server_id"), session_id=sess.get("id"))
            return {"data": sess, "meta": {"idempotent": True}}
        if sess.get("status") not in ("active", "expired"):
            _log("auth_sessions", "invalid_transition", account_id=account["id"], session_id=session_id)
            return _err("INVALID_TRANSITION", "Session cannot be revoked from its current state.")

        sess["status"] = "revoked"
        sess["updated_at"] = now_iso

        _audit("auth.session_revoked", account_id=account["id"], server_id=sess.get("server_id"), session_id=sess.get("id"),
               metadata={"changed_fields": ["status", "updated_at"]})

        _save("auth_sessions.json", sessions)
        _save("audit_events.json", audit)

        _log("auth_sessions", "ok", account_id=account["id"], server_id=sess.get("server_id"), session_id=sess.get("id"))
        return {"data": sess}

    _log("auth_sessions", "error", account_id=account["id"], detail={"error": "unreachable"})
    return _err("VALIDATION_ERROR", "Unsupported action.")

def Audit_Events(action, audit_event_id=None, server_id=None, session_id=None, cursor=None, limit=None, sort=None, filters=None, **_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0129000" if __import__("os").path.isdir("./environment_mix/0129000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    start = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now.isoformat()

    # ---- helpers ----
    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _id(prefix):
        # cgs_*_[0-9A-Z]{18,}
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        # time-based component + randomness
        ts = int(now.timestamp() * 1000)
        base = ""
        while ts > 0:
            ts, r = divmod(ts, 36)
            base = alphabet[r] + base
        base = (base or "0").rjust(10, "0")
        rand = os.urandom(8)
        r36 = ""
        acc = int.from_bytes(rand, "big")
        for _ in range(14):
            acc, r = divmod(acc, 36)
            r36 = alphabet[r] + r36
        suffix = (base + r36).rjust(18, "0")
        return f"{prefix}_{suffix}"

    def _pattern_ok(pat, v):
        if v is None:
            return True
        if not isinstance(v, str):
            return False
        return re.match(pat, v) is not None

    # ---- load store ----
    accounts = _load("accounts.json")
    servers = _load("servers.json")
    sessions = _load("auth_sessions.json")
    audit = _load("audit_events.json")

    # ---- request log / quota/rate-limits ----
    # Use audit_events as the observable call log as well (append-only).
    # Rate limit: 120 calls/minute per account; Quota: 50k calls/month per account.
    def _resolve_auth_context():
        # Ambient authentication: pick an active account that can be served.
        # Prefer one with an active session; otherwise any active account.
        active_accounts = [a for a in accounts if isinstance(a, dict) and a.get("status") == "active"]
        if not active_accounts:
            return None, None
        # Prefer account with active session
        for s in sessions:
            if isinstance(s, dict) and s.get("status") == "active":
                aid = s.get("account_id")
                acct = next((a for a in active_accounts if a.get("id") == aid), None)
                if acct:
                    # server may be null/missing; but try to resolve
                    sid = s.get("server_id")
                    srv = next((sv for sv in servers if sv.get("id") == sid), None)
                    return acct, s
        return active_accounts[0], None

    def _rate_and_quota_check(account_id):
        # count calls from special metadata marker
        # Only consider events with metadata._is_api_call == True
        window_1m = now - datetime.timedelta(minutes=1)
        month_start = now.replace(day=1, hour=0, minute=0, second=0, microsecond=0)
        c_1m = 0
        c_month = 0
        for ev in audit:
            if not isinstance(ev, dict):
                continue
            if ev.get("account_id") != account_id:
                continue
            md = ev.get("metadata")
            if not isinstance(md, dict) or not md.get("_is_api_call"):
                continue
            dt = _parse_dt(ev.get("created_at"))
            if not isinstance(dt, datetime.datetime):
                continue
            if dt >= window_1m:
                c_1m += 1
            if dt >= month_start:
                c_month += 1
        if c_1m >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded (120 calls per minute).", limit=120, window_seconds=60, used=c_1m)
        if c_month >= 50000:
            return _err("QUOTA_EXCEEDED", "Monthly quota exceeded (50,000 calls per month).", limit=50000, window="month", used=c_month)
        return {"ok": True, "used_1m": c_1m, "used_month": c_month, "month_start": month_start.isoformat()}

    def _log_call(account_id, status, endpoint, latency_ms, extra=None):
        ev = {
            "id": _id("cgs_aud"),
            "account_id": account_id,
            "server_id": server_id if isinstance(server_id, str) else None,
            "session_id": session_id if isinstance(session_id, str) else None,
            "event_type": "settings.updated",  # enum requires one; use updated as neutral call-log surrogate
            "ip_address": None,
            "user_agent": None,
            "metadata": {
                "_is_api_call": True,
                "endpoint": endpoint,
                "status": status,
                "latency_ms": latency_ms
            },
            "created_at": now_iso,
            "updated_at": now_iso
        }
        if isinstance(extra, dict):
            ev["metadata"].update(extra)
        audit.append(ev)
        _save("audit_events.json", audit)

    # ---- validate input ----
    allowed_actions = {"get", "list"}
    if action not in allowed_actions:
        # still log if possible after resolving auth
        acct, sess = _resolve_auth_context()
        if acct:
            rc = _rate_and_quota_check(acct["id"])
            if "error" not in rc:
                _log_call(acct["id"], "VALIDATION_ERROR", "Audit Events", int((time.time() - start) * 1000), {"reason": "bad_action"})
        return _err("VALIDATION_ERROR", "Invalid action.", allowed=sorted(list(allowed_actions)))

    if not _pattern_ok(r"^cgs_aud_[0-9A-Z]{18,}$", audit_event_id):
        return _err("VALIDATION_ERROR", "Invalid audit_event_id format.")
    if not _pattern_ok(r"^cgs_srv_[0-9A-Z]{18,}$", server_id):
        return _err("VALIDATION_ERROR", "Invalid server_id format.")
    if not _pattern_ok(r"^cgs_sess_[0-9A-Z]{18,}$", session_id):
        return _err("VALIDATION_ERROR", "Invalid session_id format.")
    if limit is not None:
        if not isinstance(limit, int):
            return _err("VALIDATION_ERROR", "limit must be an integer.")
        if limit < 1 or limit > 200:
            return _err("VALIDATION_ERROR", "limit must be between 1 and 200.")
    if sort is not None:
        if sort not in ("created_at", "-created_at", "updated_at", "-updated_at"):
            return _err("VALIDATION_ERROR", "Invalid sort value.")

    if filters is not None:
        if not isinstance(filters, dict):
            return _err("VALIDATION_ERROR", "filters must be an object.")
        # additionalProperties false
        for k in filters.keys():
            if k not in ("event_type", "created_after", "created_before"):
                return _err("VALIDATION_ERROR", f"Unknown filters field '{k}'.")
        if "event_type" in filters and filters["event_type"] is not None:
            if filters["event_type"] not in (
                "settings.created", "settings.updated", "settings.disabled", "settings.enabled",
                "auth.sign_in_succeeded", "auth.sign_in_failed", "auth.token_refreshed", "auth.session_revoked"
            ):
                return _err("VALIDATION_ERROR", "Invalid filters.event_type.")
        ca = _parse_dt(filters.get("created_after")) if "created_after" in filters else None
        if "created_after" in filters and filters.get("created_after") is not None and ca is None:
            return _err("VALIDATION_ERROR", "filters.created_after must be ISO 8601 date-time.")
        cb = _parse_dt(filters.get("created_before")) if "created_before" in filters else None
        if "created_before" in filters and filters.get("created_before") is not None and cb is None:
            return _err("VALIDATION_ERROR", "filters.created_before must be ISO 8601 date-time.")

    # ---- auth resolve + rate/quota ----
    acct, sess = _resolve_auth_context()
    if not acct:
        return _err("UNAUTHORIZED", "Authentication missing or invalid.")
    rq = _rate_and_quota_check(acct["id"])
    if "error" in rq:
        _log_call(acct["id"], rq["error"]["code"], "Audit Events", int((time.time() - start) * 1000))
        return rq

    # ---- implement ----
    try:
        if action == "get":
            if not audit_event_id:
                _log_call(acct["id"], "VALIDATION_ERROR", "Audit Events", int((time.time() - start) * 1000), {"reason": "missing_audit_event_id"})
                return _err("VALIDATION_ERROR", "audit_event_id is required for action='get'.")
            ev = next((e for e in audit if isinstance(e, dict) and e.get("id") == audit_event_id), None)
            if not ev:
                _log_call(acct["id"], "NOT_FOUND", "Audit Events", int((time.time() - start) * 1000))
                return _err("NOT_FOUND", "Audit event not found.")
            # Refuse access to events not owned by caller.
            if ev.get("account_id") != acct.get("id"):
                _log_call(acct["id"], "UNAUTHORIZED", "Audit Events", int((time.time() - start) * 1000))
                return _err("UNAUTHORIZED", "Not authorized to access this audit event.")
            # Optional scope checks: server_id/session_id filters for get should match if provided
            if server_id is not None and ev.get("server_id") != server_id:
                _log_call(acct["id"], "NOT_FOUND", "Audit Events", int((time.time() - start) * 1000))
                return _err("NOT_FOUND", "Audit event not found.")
            if session_id is not None and ev.get("session_id") != session_id:
                _log_call(acct["id"], "NOT_FOUND", "Audit Events", int((time.time() - start) * 1000))
                return _err("NOT_FOUND", "Audit event not found.")

            _log_call(acct["id"], "OK", "Audit Events", int((time.time() - start) * 1000))
            return {"data": ev}

        # list
        eff_limit = 50 if limit is None else limit
        # Filter to caller-owned events
        rows = [e for e in audit if isinstance(e, dict) and e.get("account_id") == acct.get("id")]

        # Optional scope filters
        if server_id is not None:
            rows = [e for e in rows if e.get("server_id") == server_id]
        if session_id is not None:
            rows = [e for e in rows if e.get("session_id") == session_id]

        if isinstance(filters, dict):
            if filters.get("event_type") is not None:
                rows = [e for e in rows if e.get("event_type") == filters["event_type"]]
            ca = _parse_dt(filters.get("created_after"))
            if ca is not None:
                rows = [e for e in rows if isinstance(_parse_dt(e.get("created_at")), datetime.datetime) and _parse_dt(e.get("created_at")) > ca]
            cb = _parse_dt(filters.get("created_before"))
            if cb is not None:
                rows = [e for e in rows if isinstance(_parse_dt(e.get("created_at")), datetime.datetime) and _parse_dt(e.get("created_at")) < cb]

        # Sort
        s = sort or "-created_at"
        reverse = s.startswith("-")
        key = s[1:] if reverse else s
        def _sort_key(e):
            v = e.get(key)
            dt = _parse_dt(v) if isinstance(v, str) else None
            return dt or datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc)
        rows.sort(key=_sort_key, reverse=reverse)

        # Cursor pagination: cursor is an event id; start after that id in current sort order.
        start_idx = 0
        if cursor is not None:
            if not isinstance(cursor, str):
                _log_call(acct["id"], "VALIDATION_ERROR", "Audit Events", int((time.time() - start) * 1000), {"reason": "bad_cursor_type"})
                return _err("VALIDATION_ERROR", "cursor must be a string.")
            # find cursor in filtered, sorted set
            for i, e in enumerate(rows):
                if e.get("id") == cursor:
                    start_idx = i + 1
                    break

        page = rows[start_idx:start_idx + eff_limit]
        has_more = (start_idx + eff_limit) < len(rows)
        next_cursor = page[-1]["id"] if (has_more and page) else None

        _log_call(acct["id"], "OK", "Audit Events", int((time.time() - start) * 1000), {"returned": len(page), "total": len(rows)})
        return {"data": page, "meta": {"total": len(rows), "limit": eff_limit, "has_more": has_more, "next_cursor": next_cursor}}
    except Exception as e:
        _log_call(acct["id"], "CONFLICT", "Audit Events", int((time.time() - start) * 1000), {"internal_error": str(e)})
        return _err("CONFLICT", "Request could not be completed due to an internal conflict.")

def Who_Am_I(action, **_extra):
    import json, os, datetime, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0129000" if __import__("os").path.isdir("./environment_mix/0129000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now.isoformat()

    def _parse_dt(s):
        if s is None or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _log(endpoint, status, account_id=None, detail=None, latency_ms=None):
        candidates = ["request_logs.json", "usage.json", "api_requests.json", "request_log.json"]
        existing = None
        for fn in candidates:
            if os.path.exists(os.path.join(_DB, fn)):
                existing = fn
                break
        if existing is None:
            return
        rows = _load(existing)
        if not isinstance(rows, list):
            rows = []
        rid = "cgs_req_" + base64.b32encode(os.urandom(12)).decode("ascii").rstrip("=")
        rows.append({
            "id": rid,
            "endpoint": endpoint,
            "status": status,
            "account_id": account_id,
            "detail": detail or {},
            "latency_ms": int(latency_ms if latency_ms is not None else (time.time() - _t0) * 1000),
            "created_at": now_iso,
        })
        _save(existing, rows)

    if action != "get":
        _log("whoami", "error", detail={"error": "invalid_action"})
        return _err("VALIDATION_ERROR", "Invalid action.")

    accounts = _load("accounts.json")
    servers = _load("servers.json")
    sessions = _load("auth_sessions.json")

    # Ambient auth must be resolvable; refuse if none.
    active_accounts = [a for a in accounts if isinstance(a, dict) and a.get("status") == "active" and isinstance(a.get("id"), str)]
    if not active_accounts:
        _log("whoami", "unauthorized")
        return _err("UNAUTHORIZED", "Authentication missing or invalid.")

    # Prefer an account that has at least one active session.
    acct = None
    for a in active_accounts:
        if any(isinstance(s, dict) and s.get("account_id") == a["id"] and s.get("status") == "active" for s in sessions):
            acct = a
            break
    if acct is None:
        acct = active_accounts[0]

    # Effective scopes: union of active session scopes
    eff_scopes = set()
    active_sess = [s for s in sessions if isinstance(s, dict) and s.get("account_id") == acct["id"] and s.get("status") == "active"]
    for s in active_sess:
        sc = s.get("scopes")
        if isinstance(sc, list):
            for x in sc:
                if isinstance(x, str):
                    eff_scopes.add(x)

    # Rate/quota consumption if request log exists
    consumption = None
    candidates = ["request_logs.json", "usage.json", "api_requests.json", "request_log.json"]
    existing = None
    for fn in candidates:
        if os.path.exists(os.path.join(_DB, fn)):
            existing = fn
            break
    if existing is not None:
        rows = _load(existing)
        if not isinstance(rows, list):
            rows = []
        one_min_ago = now - datetime.timedelta(seconds=60)
        day_ago = now - datetime.timedelta(days=1)
        m = 0
        d = 0
        for r in rows:
            if not isinstance(r, dict) or r.get("account_id") != acct["id"]:
                continue
            t = _parse_dt(r.get("created_at")) if isinstance(r.get("created_at"), str) else None
            if t is None:
                continue
            if t >= one_min_ago:
                m += 1
            if t >= day_ago:
                d += 1
        consumption = {
            "rate_limit": {"limit": 60, "window_seconds": 60, "used": m, "remaining": max(0, 60 - m)},
            "quota": {"limit": 10000, "window_seconds": 86400, "used": d, "remaining": max(0, 10000 - d)},
        }

    # Provide some server context: active servers and current session servers
    active_server_ids = set([sv.get("id") for sv in servers if isinstance(sv, dict) and sv.get("status") == "active"])
    session_server_ids = list({s.get("server_id") for s in active_sess if isinstance(s.get("server_id"), str)})

    out = {
        "account": {
            "id": acct.get("id"),
            "email": acct.get("email"),
            "display_name": acct.get("display_name"),
            "auth_provider": acct.get("auth_provider"),
            "status": acct.get("status"),
            "created_at": acct.get("created_at"),
            "updated_at": acct.get("updated_at"),
            "last_login_at": acct.get("last_login_at"),
        },
        "effective_scopes": sorted(eff_scopes),
        "active_session_count": len(active_sess),
        "active_session_server_ids": session_server_ids,
        "active_servers_available": len(active_server_ids),
    }
    if consumption is not None:
        out["consumption"] = consumption

    _log("whoami", "ok", account_id=acct["id"])
    return {"data": out}

def Sign_Out(action, session_id=None, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0129000" if __import__("os").path.isdir("./environment_mix/0129000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    accounts = _load("accounts.json")
    servers = _load("servers.json")
    settings = _load("optional_settings.json")
    sessions = _load("auth_sessions.json")
    audits = _load("audit_events.json")

    def _log_audit(account_id, server_id, session_id_val, event_type, metadata):
        nonlocal audits
        # id convention: use "cgs_aud_" prefix
        rand = os.urandom(10).hex().upper()
        aud_id = "cgs_aud_" + rand
        row = {
            "id": aud_id,
            "account_id": account_id,
            "server_id": server_id,
            "session_id": session_id_val,
            "event_type": event_type,
            "ip_address": None,
            "user_agent": None,
            "metadata": metadata if isinstance(metadata, dict) else {},
            "created_at": now,
            "updated_at": now
        }
        audits.append(row)

    def _pick_authenticated_context():
        """
        Ambient authentication: choose a working caller context from the store.
        For this endpoint, "working" means there exists at least one active session,
        and its owning account/server exist and are not deleted (account/server may be disabled/suspended
        and still allow sign-out).
        """
        acc_by_id = {a.get("id"): a for a in accounts if isinstance(a, dict) and a.get("id")}
        srv_by_id = {s.get("id"): s for s in servers if isinstance(s, dict) and s.get("id")}

        for sess in sessions:
            if not isinstance(sess, dict):
                continue
            if sess.get("status") != "active":
                continue
            aid = sess.get("account_id")
            sid = sess.get("server_id")
            acc = acc_by_id.get(aid)
            srv = srv_by_id.get(sid)
            if not acc or not srv:
                continue
            # If account is deleted, treat as not authenticated (no valid caller)
            if acc.get("status") == "deleted":
                continue
            if srv.get("status") == "deleted":
                continue
            return {"account": acc, "server": srv, "session": sess}
        return None

    def _finalize(status, body):
        # Observable dynamics: record request in audit_events as an audit trail surrogate if no request-log exists.
        # (Schema lacks request_log/usage counters; we still append a minimal audit event for the call itself is NOT required.
        # Real auditing for this endpoint is auth.session_revoked only; do not add extra events.)
        latency_ms = int((time.time() - t0) * 1000)
        if isinstance(body, dict) and "error" in body:
            body["error"].setdefault("metadata", {})
            body["error"]["metadata"].update({"latency_ms": latency_ms, "timestamp": now})
        else:
            if isinstance(body, dict):
                body.setdefault("metadata", {})
                body["metadata"].update({"latency_ms": latency_ms, "timestamp": now})
        return body

    # Validate inputs
    if action not in ("revoke_current", "revoke"):
        return _finalize(400, _err("VALIDATION_ERROR", "Invalid 'action'.", field="action"))

    if action == "revoke":
        if session_id is None or not isinstance(session_id, str) or not session_id:
            return _finalize(400, _err("VALIDATION_ERROR", "session_id is required when action='revoke'.", field="session_id"))
        if not re.match(r"^cgs_sess_[0-9A-Z]{18,}$", session_id):
            return _finalize(400, _err("VALIDATION_ERROR", "session_id does not match required pattern.", field="session_id"))
    else:
        # revoke_current: ignore provided session_id if present, but validate type if not None
        if session_id is not None and not isinstance(session_id, str):
            return _finalize(400, _err("VALIDATION_ERROR", "session_id must be a string.", field="session_id"))

    ctx = _pick_authenticated_context()
    if not ctx:
        return _finalize(401, _err("UNAUTHORIZED", "No authenticated session available."))

    caller_account = ctx["account"]
    caller_server = ctx["server"]
    caller_session = ctx["session"]

    # Resolve target session
    target = None
    if action == "revoke_current":
        target = caller_session
    else:
        # action == "revoke"
        for s in sessions:
            if isinstance(s, dict) and s.get("id") == session_id:
                target = s
                break
        if not target:
            return _finalize(404, _err("NOT_FOUND", "Session not found.", session_id=session_id))

        # Must be owned by caller
        if target.get("account_id") != caller_account.get("id"):
            return _finalize(401, _err("UNAUTHORIZED", "Session is not owned by the authenticated caller.", session_id=session_id))

    # Must be active to revoke; revoked is terminal; expired cannot be revoked? spec: "Refuses if not active"
    if target.get("status") != "active":
        return _finalize(409, _err("CONFLICT", "Session is not active and cannot be revoked.", session_id=target.get("id"), status=target.get("status")))

    # Transition active -> revoked is allowed
    # Mutate with effect
    target["status"] = "revoked"
    target["updated_at"] = now
    target["last_used_at"] = now

    # Enforce store_tokens rule: consult optional_settings referenced by session (if any), else (account_id,server_id) settings
    # If store_tokens is false, ensure token ciphertext fields are null.
    store_tokens = None
    opt_id = target.get("optional_settings_id")
    if opt_id:
        for r in settings:
            if isinstance(r, dict) and r.get("id") == opt_id:
                store_tokens = r.get("store_tokens")
                break
    if store_tokens is None:
        # fallback to unique account_id+server_id settings (active/disabled both possible)
        for r in settings:
            if not isinstance(r, dict):
                continue
            if r.get("account_id") == target.get("account_id") and r.get("server_id") == target.get("server_id"):
                store_tokens = r.get("store_tokens")
                break
    if store_tokens is False:
        target["access_token_ciphertext"] = None
        target["refresh_token_ciphertext"] = None

    # Write audit event auth.session_revoked
    _log_audit(
        account_id=target.get("account_id"),
        server_id=target.get("server_id"),
        session_id_val=target.get("id"),
        event_type="auth.session_revoked",
        metadata={"action": action}
    )

    _save("auth_sessions.json", sessions)
    _save("audit_events.json", audits)

    resp = {
        "session": target,
        "revoked": True,
        "metadata": {
            "action": action
        }
    }
    return _finalize(200, resp)
